def rank(A):
    M = [row[:] for row in A]
    m = len(M)
    n = len(M[0]) if m else 0
    r = 0
    for c in range(n):
        p = None
        for i in range(r, m):
            if abs(M[i][c]) > 1e-9:
                p = i
                break
        if p is None:
            continue
        M[r], M[p] = M[p], M[r]
        pv = M[r][c]
        for j in range(c, n):
            M[r][j] /= pv
        for i in range(m):
            if i != r and abs(M[i][c]) > 1e-9:
                f = M[i][c]
                for j in range(c, n):
                    M[i][j] -= f * M[r][j]
        r += 1
        if r == m:
            break
    return r
A = [[1, 2, -1], [2, 4, -2]]
rk = rank(A)
nullity = 3 - rk
print(nullity)
print(rk)
